INSERT INTO system.company_setting (id, singleton, company_name_en, company_name_ar, cr_number, vat_id, vat_enabled, vat_percentage, vat_certificate_url, default_currency, currency_decimals, address_en, address_ar, phone, country_code, mobile_number, whatsapp_phone, whatsapp_country_code, whatsapp_mobile_number, email, website, instagram_url, linkedin_url, youtube_url, map_url, bank_name, bank_iban, bank_account_number, bank_swift, time_zone, logo_url, dark_logo_url, full_logo_url, dark_full_logo_url, icon_url, dark_icon_url, stamp_url, signature_url, document_header_url, document_footer_url, payment_terms_days, invoice_prefix, invoice_next_number, receipt_prefix, receipt_next_number, ceo_name_en, ceo_name_ar, ceo_title_en, ceo_title_ar, ceo_quote_en, ceo_quote_ar, tagline_en, tagline_ar, about_text_en, about_text_ar, mission_en, mission_ar, vision_en, vision_ar, terms_en, terms_ar, rules_en, rules_ar, founded_year, city, country, primary_language, business_activity, default_discount_limit_percent, quotations_always_need_approval, theme, setup_completed_at, website_domain, admin_domain, updated_at) VALUES ('c0000000-0000-0000-0000-000000000001', 1, 'Marina Heights Properties W.L.L.', 'مارينا هايتس العقارية ذ.م.م', 'CR-129880-1', '200012988000002', true, 10, '/api/files/brand/stamp.png', 'BHD', 3, 'Villa 14, Lagoon Marina Promenade, Amwaj Islands', 'فيلا 14، ممشى لاغون مارينا، جزر أمواج', '+97316012200', 'BH', '16012200', '+97338012200', 'BH', '38012200', 'listings@marinaheights.bh', 'https://marinaheights.bh', 'https://instagram.com/marina-heights', 'https://linkedin.com/company/marina-heights', 'https://youtube.com/@marina-heights', 'https://maps.google.com/?q=Amwaj%20Islands%2C%20Bahrain', 'Kuwait Finance House (KFH)', 'BH33KFHO00000029880001', '0029880001', 'KFHOBHBM', 'Asia/Bahrain', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/icon-light.png', '/api/files/brand/icon-dark.png', '/api/files/brand/stamp.png', '/api/files/brand/signature.png', '/api/files/media/banners/banner-01.png', '/api/files/media/banners/banner-02.png', 30, 'MHP', 150, 'RCT', 150, 'Hessa Al-Khalifa', 'حصة آل خليفة', 'Chief Executive Officer', 'الرئيسة التنفيذية', 'Precision delivery from Amwaj Islands across the GCC.', 'التميز التشغيلي من Amwaj Islands إلى جميع أسواق الخليج.', 'Waterfront Residences, Commercial Towers & Asset Management', 'المساكن البحرية والأبراج التجارية وإدارة الأملاك', 'Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing.', 'شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية.', 'Deliver benchmark real estate services with clear bilingual accountability.', 'تقديم خدمات موثوقة ثنائية اللغة وفق أعلى معايير الجودة والالتزام.', 'To lead Bahrain''s enterprise ecosystem in real estate innovation.', 'أن نكون الشريك المرجعي الأول لقطاع الأعمال في مملكة البحرين والخليج.', 'Invoices are payable within 30 calendar days in BHD. Late balances accrue documented reminders.', 'تستحق الفواتير خلال 30 يوماً بعملة BHD وفق شروط العقد المعتمد.', '10% VAT compliant with Bahrain NBR e-invoicing guidelines; signed approvals logged digitally.', 'تطبق ضريبة القيمة المضافة 10% وفق متطلبات الجهاز الوطني للإيرادات.', 2016, 'Amwaj Islands', 'BH', 'ar', 'real_estate', 15, false, '{"primary":"#134E4A","accent":"#0EA5E9","radius":"md","defaultMode":"light","fonts":{"body":{"kind":"google","family":"Plus Jakarta Sans"},"heading":{"kind":"google","family":"Plus Jakarta Sans"}}}'::jsonb, '2026-01-01T00:00:00Z', 'marinaheights.bh', 'admin.marinaheights.bh', now()) ON CONFLICT (id) DO NOTHING;
