INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'marina-heights-case-1', 'Amwaj Waterfront 24-Villa Management', 'إدارة 24 فيلا بحرية في جزر أمواج', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Amwaj Islands with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Amwaj Islands وفق أعلى معايير الجودة والالتزام.', 1700, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://marinaheights.bh/work/marina-heights-case-1', 'Amwaj Islands, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'marina-heights-2026-outlook', 'Marina Heights 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مارينا هايتس', 'Key operational benchmarks, real metrics, and 2026 guidance from Marina Heights in Amwaj Islands.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مارينا هايتس في Amwaj Islands.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing. Focusing on Full Building Property Management, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية. من خلال خدمة إدارة عقارية شاملة للمباني نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing.</p><p>Focusing on <strong>Full Building Property Management</strong>, our Amwaj Islands specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية.</p><p>من خلال خدمة <strong>إدارة عقارية شاملة للمباني</strong>، يعمل فريقنا في Amwaj Islands على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Marina Heights 2026 GCC Market Outlook & Benchmarks | Marina Heights', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مارينا هايتس | مارينا هايتس', 'Executive guide by Marina Heights covering Full Building Property Management benchmarks in Bahrain.', 'دليل تنفيذي من مارينا هايتس حول معايير إدارة عقارية شاملة للمباني في البحرين.', 'Insights', '{"real_estate","insights","Amwaj Islands","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Marina Heights initiate a Full Building Property Management engagement?', 'كم يستغرق بدء تنفيذ خدمة إدارة عقارية شاملة للمباني لدى مارينا هايتس؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Amwaj Islands.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Amwaj Islands.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'marina-heights-case-2', 'Seef Grade-A Commercial Plaza Leasing', 'تأجير المجمع المكتبي الفاخر بضاحية السيف', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Amwaj Islands with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Amwaj Islands وفق أعلى معايير الجودة والالتزام.', 540, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://marinaheights.bh/work/marina-heights-case-2', 'Amwaj Islands, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'marina-heights-service-standards', 'Inside Our Management SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في إدارة عقارية شاملة للمباني', 'Key operational benchmarks, real metrics, and 2026 guidance from Marina Heights in Amwaj Islands.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مارينا هايتس في Amwaj Islands.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing. Focusing on RERA Certified Property Valuation, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية. من خلال خدمة تقييم عقاري معتمد نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing.</p><p>Focusing on <strong>RERA Certified Property Valuation</strong>, our Amwaj Islands specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية.</p><p>من خلال خدمة <strong>تقييم عقاري معتمد</strong>، يعمل فريقنا في Amwaj Islands على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Management SLA: Speed, Quality & Auditability | Marina Heights', 'معايير اتفاقية مستوى الخدمة والجودة في إدارة عقارية شاملة للمباني | مارينا هايتس', 'Executive guide by Marina Heights covering RERA Certified Property Valuation benchmarks in Bahrain.', 'دليل تنفيذي من مارينا هايتس حول معايير تقييم عقاري معتمد في البحرين.', 'Operations', '{"real_estate","operations","Amwaj Islands","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-129880-1 and VAT ID 200012988000002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-129880-1 والرقم الضريبي 200012988000002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
